56	  protected override validateToolParamValues(
57	    params: ExitPlanModeParams,
58	  ): string | null {
59	    if (!params.plan_path || params.plan_path.trim() === '') {
60	      return 'plan_path is required.';
61	    }
62	
63	    // Since validateToolParamValues is synchronous, we use a basic synchronous check
64	    // for path traversal safety. High-level async validation is deferred to shouldConfirmExecute.
65	    const plansDir = resolveToRealPath(this.config.storage.getPlansDir());
66	    const resolvedPath = path.resolve(
67	      this.config.getTargetDir(),
68	      params.plan_path,
69	    );
70	
71	    const realPath = resolveToRealPath(resolvedPath);
72	
73	    if (!isSubpath(plansDir, realPath)) {
74	      return `Access denied: plan path must be within the designated plans directory.`;
75	    }
76	
77	    return null;
78	  }
